import java.io.FileReader;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;

public class FileReaderExample {
    public static void main(String[] args) {
        try {
            // Fixed: Using Files.readAllLines to read the file content as a list of strings
            List<String> lines = Files.readAllLines(Paths.get("user_input.txt"));
            if (!lines.isEmpty()) {
                String userInput = lines.get(0).trim(); // Fixed: Trimming the input to remove leading/trailing whitespaces
                System.out.println("User input: " + userInput);
            } else {
                System.out.println("No input found.");
